package com.qfk.match.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="matches") public class FootballMatch {@Id @GeneratedValue(strategy=GenerationType.UUID) public UUID id; @Version public long version; @Column(nullable=false,unique=true) public long matchNumber; @Column(nullable=false) public String title; @Enumerated(EnumType.STRING) public MatchType type; @Enumerated(EnumType.STRING) public MatchStatus status; public Instant startsAt; public Instant endsAt; public String venue; public int maximumPlayers; @Column(precision=12,scale=2) public BigDecimal registrationFee; @Column(nullable=false,length=3) public String currency="QAR"; public enum MatchType{COMMUNITY_MATCH,FRIENDLY,TOURNAMENT,PRACTICE,INTERNAL,EXTERNAL} public enum MatchStatus{DRAFT,REGISTRATION_SCHEDULED,REGISTRATION_OPEN,FULL,REGISTRATION_CLOSED,TEAM_SELECTION,CONFIRMED,IN_PROGRESS,COMPLETED,CANCELLED}}
